import test from 'node:test';
import assert from 'node:assert/strict';
import { percentOf } from '../src/money.js';

test('percentOf rounds to the nearest cent', () => {
  assert.equal(percentOf(1999, 15), 300); // 299.85 rounds up
  assert.equal(percentOf(1699, 8), 136); // 135.92 rounds up
  assert.equal(percentOf(1000, 10), 100);
  assert.equal(percentOf(1, 1), 0); // 0.01 rounds down
});

test('percentOf rounds exact halves up', () => {
  assert.equal(percentOf(50, 15), 8); // 7.5 rounds up, not 7
  assert.equal(percentOf(1, 50), 1); // 0.5 rounds up, not 0
  assert.equal(percentOf(3, 50), 2); // 1.5 rounds up, not 1
});

